  page?: {
    waitForSelector?: (
      selector: string,
      options?: { state?: WaitState; timeout?: number }
    ) => Promise<unknown>;
    evaluate?: <T>(fn: (...args: any[]) => T, ...args: any[]) => Promise<T>;
    locator?: (selector: string) => TargetLocator;
    getByRole?: (role: never, options?: { name?: string; exact?: boolean }) => TargetLocator;
    getByText?: (text: string, options?: { exact?: boolean }) => TargetLocator;
  };
  url?: (() => Promise<string> | string) | string;
};

function sessionDetails(session: SessionLike, url: string) {
  return {
    ...baseSessionDetails(session),
    url,
  };
}

function resolveTimeout(rawTimeout?: number): number {
  return resolveToolTimeoutMs(rawTimeout);
}

function resolveState(rawState?: string): WaitState {
  if (rawState === "attached") {
    return "attached";
  }
  return "visible";
}

async function readSessionUrl(session: SessionLike): Promise<string> {
  const direct = session.url;
  if (typeof direct === "string" && direct.trim()) {
    return direct;
  }

  if (typeof direct === "function") {
    const value = await direct.call(session);
    if (typeof value === "string" && value.trim()) {
      return value;
    }
  }

  const getter = (session as { getCurrentUrl?: () => Promise<string> | string }).getCurrentUrl;
  if (typeof getter === "function") {
    const value = await getter.call(session);
    if (typeof value === "string" && value.trim()) {
      return value;
    }
  }

  return "unknown";
}

export function waitTool(client: SteelClient): ToolDefinition<any, any> {
  return {
    name: "steel_wait",
    label: "Wait",
    description:
      "Wait for an element by CSS selector, ARIA role/name, or visible text.",
    parameters: Type.Object({
      ...targetParameterProperties,
      timeout: Type.Optional(
        Type.Integer({
          minimum: MIN_TOOL_TIMEOUT_MS,
          maximum: MAX_TOOL_TIMEOUT_MS,
          description: "Maximum milliseconds to wait for selector state",
        })
      ),
      state: Type.Optional(
        Type.Union([Type.Literal("attached"), Type.Literal("visible")], {
          description: "Selector state to wait for",
        })
      ),
    }),

    async execute(
      _toolCallId: string,
      params: BrowserTargetInput & { timeout?: number; state?: WaitState },
      signal: AbortSignal | undefined,
      onUpdate: ToolProgressUpdater,
      _ctx: ExtensionContext
    ): Promise<{ content: Array<{ type: "text"; text: string }>; details: object }> {
      return withToolError("steel_wait", async () => {
        throwIfAborted(signal);
        const target = resolveTarget(params);
        const targetLabel = describeTarget(target);
        const timeoutMs = resolveTimeout(params.timeout);
        const state = resolveState(params.state);
        const session = (await withAbortSignal(client.getOrCreateSession(), signal)) as SessionLike;
        throwIfAborted(signal);
        const url = await readSessionUrl(session);

        await emitProgress(onUpdate, "steel_wait", `Waiting for ${targetLabel} with state ${state}`);

        try {
          const locator = getTargetLocator(session, target);
          if (!locator.waitFor) {
            throw new Error(`Session does not support waiting for ${targetLabel}.`);
          }
          await withAbortSignal(locator.waitFor({ state, timeout: timeoutMs }), signal);
        } catch (error) {
          const message = String(error instanceof Error ? error.message : "");
          if (/timed? ?out|timeout/i.test(message)) {
            throw new Error(`Timed out waiting for ${targetLabel} after ${timeoutMs}ms.`);
          }

          throw error instanceof Error
            ? error
            : new Error(`Failed to wait for ${targetLabel}`);
        }

        await emitProgress(onUpdate, "steel_wait", `Matched ${targetLabel}`);

        return {
          content: [{
            type: "text",
            text: `Target matched: ${targetLabel}`,
          }],
          details: {
            ...sessionDetails(session, url),
            target,
            selector: target.kind === "selector" ? target.selector : null,
            state,
            timeoutMs,
            success: true,
          },
        };
      }, signal);
    },
  };
}

import type { ExtensionContext, ToolDefinition } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { sessionDetails, type SteelClient } from "../steel-client.js";
import {
  emitProgress,
  throwIfAborted,
  withAbortSignal,
  withToolError,
  type ToolProgressUpdater,
} from "./tool-runtime.js";
import {
  blankPageError,
  describeBlankPage,
  isBlankPageUrl,
  readSessionTitle,
  readSessionUrl,
} from "./session-state.js";

type SessionLike = {
  id: string;
  sessionViewerUrl?: string | null;
  goBack?: (options?: { waitUntil?: "load" | "domcontentloaded" | "networkidle"; timeout?: number }) => Promise<unknown> | unknown;
  back?: (options?: { waitUntil?: "load" | "domcontentloaded" | "networkidle"; timeout?: number }) => Promise<unknown> | unknown;
  url?: (() => Promise<string> | string) | string;
  title?: (() => Promise<string> | string) | string;
  getCurrentUrl?: () => Promise<string> | string;
};

const GO_BACK_TIMEOUT_MS = 10_000;

function isTimeoutError(error: unknown): boolean {
  const message = String(error instanceof Error ? error.message : error || "");
  return /timed? ?out|timeout/i.test(message);
}

export function goBackTool(client: SteelClient): ToolDefinition<any, any> {
  return {
    name: "steel_go_back",
    label: "Go Back",
    description: "Navigate back in browser history",
    parameters: Type.Object({}),

    async execute(
      _toolCallId: string,
      _params: {},
      signal: AbortSignal | undefined,
      onUpdate: ToolProgressUpdater,
      _ctx: ExtensionContext
    ): Promise<{ content: Array<{ type: "text"; text: string }>; details: object }> {
      return withToolError("steel_go_back", async () => {
        throwIfAborted(signal);
        await emitProgress(onUpdate, "steel_go_back", "Preparing history navigation");

        const session = (await withAbortSignal(
          client.getOrCreateSession(),
          signal
        )) as SessionLike;
        const previousUrl = await readSessionUrl(session);
        const goBack = session.goBack ?? session.back;

        if (typeof goBack !== "function") {
          throw new Error("Session does not support browser history navigation.");
        }

        await emitProgress(onUpdate, "steel_go_back", "Returning to previous page");
        let timeoutRecovered = false;

        try {
          await withAbortSignal(
            Promise.resolve(
              goBack.call(session, {
                waitUntil: "domcontentloaded",
                timeout: GO_BACK_TIMEOUT_MS,
              })
            ),
            signal
          );
        } catch (error: unknown) {
          const currentUrlAfterFailure = await readSessionUrl(session);
          if (
            isTimeoutError(error) &&
            currentUrlAfterFailure !== "unknown" &&
            currentUrlAfterFailure !== previousUrl &&
            !isBlankPageUrl(currentUrlAfterFailure)
          ) {
            timeoutRecovered = true;
            await emitProgress(
              onUpdate,
              "steel_go_back",
              `History navigation completed after timeout; now at ${currentUrlAfterFailure}`
            );
          } else {
            throw error;
          }
        }

        const currentUrl = await readSessionUrl(session);
        await emitProgress(onUpdate, "steel_go_back", `Returned to ${currentUrl}`);

        return {
          content: [{
            type: "text",
            text: `Navigated back to ${currentUrl}`,
          }],
          details: {
            ...sessionDetails(session),
            previousUrl,
            url: currentUrl,
            timeoutRecovered,
          },
        };
      }, signal);
    },
  };
}

export function getUrlTool(client: SteelClient): ToolDefinition<any, any> {
  return {
    name: "steel_get_url",
    label: "Get URL",
    description: "Get current page URL",
    parameters: Type.Object({}),

    async execute(
      _toolCallId: string,
      _params: {},
      signal: AbortSignal | undefined,
      onUpdate: ToolProgressUpdater,
      _ctx: ExtensionContext
    ): Promise<{ content: Array<{ type: "text"; text: string }>; details: object }> {
      return withToolError("steel_get_url", async () => {
        throwIfAborted(signal);
        await emitProgress(onUpdate, "steel_get_url", "Reading current URL");
        const session = (await withAbortSignal(
          client.getOrCreateSession(),
          signal
        )) as SessionLike;
        const url = await readSessionUrl(session);
        const isFreshSession = isBlankPageUrl(url);
        const text = isFreshSession ? describeBlankPage(url) : `Current URL: ${url}`;

        return {
          content: [{ type: "text", text }],
          details: {
            ...sessionDetails(session),
            url,
            isFreshSession,
          },
        };
      }, signal);
    },
  };
}

export function getTitleTool(client: SteelClient): ToolDefinition<any, any> {
  return {
    name: "steel_get_title",
    label: "Get Title",
    description: "Get current page title",
    parameters: Type.Object({}),

    async execute(
      _toolCallId: string,
      _params: {},
      signal: AbortSignal | undefined,
      onUpdate: ToolProgressUpdater,
      _ctx: ExtensionContext
    ): Promise<{ content: Array<{ type: "text"; text: string }>; details: object }> {
      return withToolError("steel_get_title", async () => {
        throwIfAborted(signal);
        await emitProgress(onUpdate, "steel_get_title", "Reading current page title");
        const session = (await withAbortSignal(
          client.getOrCreateSession(),
          signal
        )) as SessionLike;
        const url = await readSessionUrl(session);
        if (isBlankPageUrl(url)) {
          throw blankPageError("read the page title");
        }
        const title = await readSessionTitle(session);

        return {
          content: [{ type: "text", text: `Current title: ${title}` }],
          details: {
            ...sessionDetails(session),
            url,
            title,
          },
        };
      }, signal);
    },
  };
}

const DEFAULT_TOOL_TIMEOUT_MS = 30_000;
const TOOL_TIMEOUT_ENV = "STEEL_TOOL_TIMEOUT_MS";
export const MIN_TOOL_TIMEOUT_MS = 100;
export const MAX_TOOL_TIMEOUT_MS = 120_000;

let cachedDefaultToolTimeoutMs: number | null = null;

function parsePositiveInt(raw: string | undefined): number | null {
  if (raw === undefined) {
    return null;
  }

  const value = raw.trim();
  if (!value) {
    return null;
  }

  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
}

export function getDefaultToolTimeoutMs(): number {
  if (cachedDefaultToolTimeoutMs !== null) {
    return cachedDefaultToolTimeoutMs;
  }

  const parsed = parsePositiveInt(process.env[TOOL_TIMEOUT_ENV]);
  if (parsed === null) {
    cachedDefaultToolTimeoutMs = DEFAULT_TOOL_TIMEOUT_MS;
    return cachedDefaultToolTimeoutMs;
  }

  cachedDefaultToolTimeoutMs = Math.max(
    MIN_TOOL_TIMEOUT_MS,
    Math.min(parsed, MAX_TOOL_TIMEOUT_MS)
  );
  return cachedDefaultToolTimeoutMs;
}

export function resolveToolTimeoutMs(rawTimeout: number | undefined): number {
  if (rawTimeout === undefined) {
    return getDefaultToolTimeoutMs();
  }

  const parsed = Number(rawTimeout);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error("timeout must be a positive number in milliseconds.");
  }

  const rounded = Math.max(MIN_TOOL_TIMEOUT_MS, Math.trunc(parsed));
  return Math.min(rounded, MAX_TOOL_TIMEOUT_MS);
}

import { Type } from "typebox";

export type BrowserTargetInput = {
  selector?: string;
  role?: string;
  name?: string;
  targetText?: string;
  exact?: boolean;
};

export type BrowserTarget =
  | { kind: "selector"; selector: string }
  | { kind: "role"; role: string; name?: string; exact: boolean }
  | { kind: "text"; text: string; exact: boolean };

export type TargetLocator = {
  waitFor?: (options?: {
    state?: "attached" | "visible";
    timeout?: number;
  }) => Promise<unknown>;
  isVisible?: () => Promise<boolean>;
  isEnabled?: () => Promise<boolean>;
  click?: (options?: { timeout?: number }) => Promise<unknown>;
  fill?: (value: string, options?: { timeout?: number }) => Promise<unknown>;
  pressSequentially?: (
    value: string,
    options?: { delay?: number; timeout?: number }
  ) => Promise<unknown>;
  screenshot?: (options?: { path?: string; timeout?: number }) => Promise<unknown>;
};

type LocatorFactory = {
  locator?: (selector: string) => TargetLocator;
  getByRole?: (
    role: never,
    options?: { name?: string; exact?: boolean }
  ) => TargetLocator;
  getByText?: (text: string, options?: { exact?: boolean }) => TargetLocator;
  waitForSelector?: (
    selector: string,
    options?: { state?: "attached" | "visible"; timeout?: number }
  ) => Promise<unknown>;
  click?: (selector: string, options?: { timeout?: number }) => Promise<unknown>;
  fill?: (selector: string, value: string) => Promise<unknown>;
  type?: (
    selector: string,
    value: string,
    options?: { delay?: number }
  ) => Promise<unknown>;
};

type TargetSession = LocatorFactory & {
  page?: LocatorFactory;
};

export const targetParameterProperties = {
  selector: Type.Optional(
    Type.String({ description: "CSS or Playwright selector for the target element" })
  ),
  role: Type.Optional(
    Type.String({
      description: "ARIA role for semantic targeting, such as button, link, or textbox",
    })
  ),
  name: Type.Optional(
    Type.String({ description: "Accessible name used with role targeting" })
  ),
  targetText: Type.Optional(
    Type.String({ description: "Visible text used for semantic targeting" })
  ),
  exact: Type.Optional(
    Type.Boolean({
      description: "Require an exact accessible-name or text match (default false)",
    })
  ),
};

function nonEmpty(value: string | undefined): string | undefined {
  const trimmed = value?.trim();
  return trimmed || undefined;
}

export function resolveTarget(input: BrowserTargetInput): BrowserTarget {
  const selector = nonEmpty(input.selector);
  const role = nonEmpty(input.role);
  const name = nonEmpty(input.name);
  const text = nonEmpty(input.targetText);
  const methods = [selector ? "selector" : null, role ? "role" : null, text ? "text" : null].filter(
    Boolean
  );

  if (methods.length === 0) {
    throw new Error("Provide one target: selector, role, or text.");
  }
  if (methods.length > 1) {
    throw new Error("Provide only one target method: selector, role, or text.");
  }
  if (name && !role) {
    throw new Error("name can only be used with role targeting.");
  }

  if (selector) {
    return { kind: "selector", selector };
  }
  if (role) {
    return { kind: "role", role, ...(name ? { name } : {}), exact: input.exact ?? false };
  }
  return { kind: "text", text: text!, exact: input.exact ?? false };
}

export function describeTarget(target: BrowserTarget): string {
  if (target.kind === "selector") {
    return `selector ${target.selector}`;
  }
  if (target.kind === "role") {
    return target.name
      ? `role ${target.role} named "${target.name}"`
      : `role ${target.role}`;
  }
  return `text "${target.text}"`;
}

export function getTargetLocator(
  session: TargetSession,
  target: BrowserTarget
): TargetLocator {
  const page = session.page ?? session;

  if (target.kind === "selector") {
    const locator = session.locator?.(target.selector) ?? page.locator?.(target.selector);
    if (locator) {
      return locator;
    }

    const legacy = session.waitForSelector || session.click || session.fill || session.type
      ? session
      : page;
    if (legacy.waitForSelector || legacy.click || legacy.fill || legacy.type) {
      return {
        waitFor: legacy.waitForSelector
          ? (options) => legacy.waitForSelector!(target.selector, options)
          : undefined,
        click: legacy.click
          ? (options) => legacy.click!(target.selector, options)
          : undefined,
        fill: legacy.fill
          ? (value) => legacy.fill!(target.selector, value)
          : undefined,
        pressSequentially: legacy.type
          ? (value, options) =>
              legacy.type!(target.selector, value, { delay: options?.delay })
          : undefined,
      };
    }
  } else if (target.kind === "role") {
    const locator = page.getByRole?.(target.role as never, {
      ...(target.name ? { name: target.name } : {}),
      exact: target.exact,
    });
    if (locator) {
      return locator;
    }
  } else {
    const locator = page.getByText?.(target.text, { exact: target.exact });
    if (locator) {
      return locator;
    }
  }

  throw new Error(`Session does not support ${describeTarget(target)} targeting.`);
}

import type { AgentToolUpdateCallback } from "@earendil-works/pi-coding-agent";

export type ToolErrorCategory =
  | "validation"
  | "timeout"
  | "network"
  | "tool_execution"
  | "unknown";

export type ToolProgressUpdater = AgentToolUpdateCallback<{
  context: string;
  kind: "progress";
  message: string;
}> | undefined;

const ABORT_ERROR_NAME = "AbortError";
const ABORT_ERROR_MESSAGE = "Tool execution cancelled.";

const TOOL_ERROR_PATTERNS: Record<ToolErrorCategory, readonly string[]> = {
  validation: [
    "bad request",
    "invalid",
    "missing",
    "required",
    "schema",
    "format",
    "validation",
    "unsupported value",
    "not allowed",
  ],
  timeout: [
    "timed out",
    "timeout",
    "timed-out",
    "deadline",
    "time out",
  ],
  network: [
    "network",
    "connection",
    "econn",
    "enotfound",
    "dns",
    "econnreset",
    "econnrefused",
    "proxy",
    "ssl",
    "certificate",
  ],
  tool_execution: [
    "selector",
    "tool",
    "navigation",
    "screenshot",
    "pdf",
    "session",
    "click",
    "extract",
    "not supported",
    "page",
  ],
  unknown: [],
};

const TOOL_ERROR_LABELS: Record<ToolErrorCategory, string> = {
  validation: "Validation failed",
  timeout: "Timed out",
  network: "Network issue",
  tool_execution: "Tool execution failed",
  unknown: "Tool error",
};

const TOOL_ERROR_GUIDANCE: Record<ToolErrorCategory, string> = {
  validation: "Check required inputs and retry with corrected values.",
  timeout:
    "Retry with narrower scope or longer timeout values.",
  network:
    "Retry once connectivity is stable.",
  tool_execution:
    "Retrying usually succeeds; if selector-based operations fail, refresh page state and try again.",
  unknown: "Retry the action and, if it repeats, rerun with simplified inputs.",
};

function normalizeErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message?.trim() || "Unknown error";
  }

  if (typeof error === "string") {
    return error.trim() || "Unknown error";
  }

  if (error === undefined || error === null) {
    return "Unknown error";
  }

  try {
    return JSON.stringify(error);
  } catch {
    return String(error);
  }
}

function classifyError(message: string): ToolErrorCategory {
  const normalized = message.toLowerCase();

  for (const [category, markers] of Object.entries(
    TOOL_ERROR_PATTERNS
  ) as [ToolErrorCategory, readonly string[]][]) {
    if (markers.some((marker) => normalized.includes(marker))) {
      return category;
    }
  }
  return "unknown";
}

export function toolErrorMessage(context: string, error: unknown): string {
  const message = normalizeErrorMessage(error);
  const category = classifyError(message);
  const label = TOOL_ERROR_LABELS[category];
  const guidance = TOOL_ERROR_GUIDANCE[category];
  return `${context}: ${label}. ${message}. Retry guidance: ${guidance}`;
}

export class SteelToolError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SteelToolError";
  }
}

export function toolError(context: string, error: unknown): Error {
  if (error instanceof SteelToolError) {
    return error;
  }
  return new SteelToolError(toolErrorMessage(context, error));
}

function abortError(message = ABORT_ERROR_MESSAGE): Error {
  const error = new Error(message);
  error.name = ABORT_ERROR_NAME;
  return error;
}

export function isAbortError(error: unknown): boolean {
  if (!(error instanceof Error)) {
    return false;
  }
  if (error.name === ABORT_ERROR_NAME) {
    return true;
  }

  const message = error.message.toLowerCase();
  return message.includes("cancelled") || message.includes("canceled");
}

export function throwIfAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted) {
    throw abortError();
  }
}

export function sleepWithSignal(
  ms: number,
  signal: AbortSignal | undefined
): Promise<void> {
  if (!signal) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  throwIfAborted(signal);

  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      signal.removeEventListener("abort", onAbort);
      reject(abortError());
    };
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

export function withAbortSignal<T>(
  promise: Promise<T>,
  signal: AbortSignal | undefined
): Promise<T> {
  if (!signal) {
    return promise;
  }

  throwIfAborted(signal);

  return new Promise((resolve, reject) => {
    const onAbort = () => {
      signal.removeEventListener("abort", onAbort);
      reject(abortError());
    };

    signal.addEventListener("abort", onAbort, { once: true });
    promise.then(
      (value) => {
        signal.removeEventListener("abort", onAbort);
        resolve(value);
      },
      (error: unknown) => {
        signal.removeEventListener("abort", onAbort);
        reject(error);
      }
    );
  });
}

export function withToolError<T>(
  context: string,
  operation: () => Promise<T>,
  signal?: AbortSignal
): Promise<T> {
  try {
    throwIfAborted(signal);
    return operation().catch((error: unknown) => {
      if (isAbortError(error) || signal?.aborted) {
        throw abortError(`${context}: ${ABORT_ERROR_MESSAGE}`);
      }
      if (error instanceof SteelToolError) {
        throw error;
      }
      throw toolError(context, error);
    });
  } catch (error: unknown) {
    if (isAbortError(error) || signal?.aborted) {
      throw abortError(`${context}: ${ABORT_ERROR_MESSAGE}`);
    }
    if (error instanceof SteelToolError) {
      throw error;
    }
    throw toolError(context, error);
  }
}

export function emitProgress(
  onUpdate: ToolProgressUpdater,
  context: string,
  message: string
): void {
  if (!onUpdate) {
    return;
  }

  const trimmed = message.trim();
  onUpdate({
    content: [{ type: "text", text: `${context}: ${trimmed}` }],
    details: {
      context,
      kind: "progress",
      message: trimmed,
    },
  });
}
